module TopModule(
    input wire clk,
    input wire rst,
    input wire d1,
    input wire d2,
    input wire sel,
    output reg out1,
    output reg out2,
    output reg out3
);

    reg [3:0] amount;
    reg [3:0] next_amount;
    wire [3:0] price = sel ? 5 : 3; // 2.5 yuan = 5 * 0.5, 1.5 yuan = 3 * 0.5

    always @(posedge clk or negedge rst) begin
        if (!rst)
            amount <= 0;
        else
            amount <= next_amount;
    end

    always @(*) begin
        if (amount >= price)
            next_amount = 0;
        else
            next_amount = amount + (d1 ? 1 : 0) + (d2 ? 2 : 0);
    end

    always @(*) begin
        if (!rst) begin
            out1 = 0;
            out2 = 0;
            out3 = 0;
        end else if (amount >= price) begin
            out1 = (sel == 0);
            out2 = (sel == 1);
            out3 = (amount > price);
        end else begin
            out1 = 0;
            out2 = 0;
            out3 = 0;
        end
    end

endmodule
